WITH src AS (SELECT * FROM subscriptions WHERE YEAR(end_date) = 2024 OR YEAR(start_date) = 2023), start_quarter_summary AS (SELECT QUARTER(start_date) AS start_quarter, SUM(CASE WHEN status = 'EXPIRED' THEN 1 ELSE 0 END) AS expired_count, SUM(CASE WHEN status = 'ACTIVE' THEN 1 ELSE 0 END) AS active_count FROM src GROUP BY QUARTER(start_date)) SELECT * FROM start_quarter_summary WHERE active_count > 53;
